import time
class Solution:
    def dailyTemperatures(self,temperatures):
        n=len(temperatures)
        stack=[]
        ans=[0]*n

        for i in range(n):

            while stack and temperatures[i]>temperatures[stack[-1]]:
                pre_index=stack.pop()
                ans[pre_index]=i-pre_index

            stack.append(i)

        return ans


